export function makeT(locale: string) {
  const L: Locale = (LOCALES as string[]).includes(locale) ? (locale as Locale) : 'en';
  return (key: string, params?: Record<string, string | number>): string => {
    const entry = MSG[key];
    let s = entry ? (entry[L] ?? entry.en) : key;
    if (params) {
      for (const p of Object.keys(params)) {
        s = s.split('{' + p + '}').join(String(params[p]));
      }
    }
    return s;
  };
}
